pub fn retire(self:*Boundary,host_error:?anyerror,scope:*v.Scope,values:[]c.JSValue)void{
    self.start();self.observe(null);
    if(host_error) |err| { if(err==error.JavaScriptException and self.reason==null)self.escaping(); }
    // A trusted direct host allocation failure precedes root retirement.
    if(host_error) |err| { if(err==error.OutOfMemory and !self.isFatal()){_=self.engine.throwNativeOutOfMemoryFatal();self.observe(null);} }
    const count=scope.inline_count;scope.inline_count=0;for(scope.inline_values[0..count])|*value|self.release(value);
    const dynamic=scope.values.items;scope.values.items=dynamic[0..0];for(dynamic)|*value|self.release(value);
    const generation=self.engine.native_allocation_generation;scope.values.deinit(self.engine.gpa);self.observe(generation);
    if(host_error!=null or self.reason!=null)self.failureRoots(values)
    else if(self.engine.captured_exception==null){self.engine.captured_exception=self.previous;self.previous=null;}
    else if(self.previous)|value|{self.previous=null;var old=value;self.release(&old);}
    if(host_error!=null or self.reason!=null)self.failureRoots(values);
}
pub fn failed(self:*Boundary,host_error:?anyerror)bool{self.observe(null);return host_error!=null or self.reason!=null;}
pub fn finishRetired(self:*Boundary,host_error:?anyerror,values:[]c.JSValue)!void{
    defer self.engine.native_exception_diagnostics_suppressed-=1;
    self.observe(null);
    if(host_error!=null or self.reason!=null)self.failureRoots(values);
    // Pop at the caller-stable address before returning any completion.
    self.finished=true;
    const result=self.engine.leaveNativeInvocation(&self.invocation,c.pi_js_undefined());
    self.engine.freeValue(result); // Undefined/exception sentinel only.
    self.observe(null); // finished prevents relinking the dead frame.
    if(host_error!=null or self.reason!=null)self.failureRoots(values);
    if(self.reason)|value|{
        const termination=self.isTermination();
        self.reason=null;self.reason_pending=false;
        if(!termination){
            if(self.fatal)c.JS_SetUncatchableError(self.engine.context,value)
            else c.JS_ClearUncatchableError(self.engine.context,value);
        }
        _=self.engine.checked(c.JS_Throw(self.engine.context,value)) catch |err|return err;
        return error.ActualCommonJSBoundaryThrowDidNotFail;
    }
    if(host_error)|err|return err;
}
pub fn finishMany(self:*Boundary,host_error:?anyerror,scope:*v.Scope,values:[]c.JSValue)!void{self.retire(host_error,scope,values);return self.finishRetired(host_error,values);}
pub fn finish(self:*Boundary,completion:anyerror!c.JSValue,scope:*v.Scope)!c.JSValue{
    var values=[_]c.JSValue{c.pi_js_undefined()};var host_error:?anyerror=null;
    if(completion)|value|values[0]=value else |err|host_error=err;
    try self.finishMany(host_error,scope,&values);return values[0];
}

/// Consumes one actual owned native root in the caller's original order.
pub fn release(self: *Completion, value: c.JSValue) void {
    std.debug.assert(!self.finished);
    self.enter();
    const generation = self.owner.engine.native_allocation_generation;
    self.owner.engine.freeValue(value);
    self.owner.events(generation);
}

pub fn finishValue(self: *Completion) anyerror!c.JSValue {
    return switch (try self.finishAction()) {
        .returned => |value| value,
        .thrown => |reason| self.owner.engine.checked(c.JS_Throw(self.owner.engine.context, reason)),
        .awaited => unreachable,
    };
}
pub fn finishVoid(self: *Completion) anyerror!void {
    switch (try self.finishAction()) {
        .returned => |value| self.owner.engine.freeValue(value),
        .thrown => |reason| { _ = try self.owner.engine.checked(c.JS_Throw(self.owner.engine.context, reason)); unreachable; },
        .awaited => unreachable,
    }

pub fn close(self: *Scope) !void {
    std.debug.assert(self.initialized and !self.deinitialized);
    if (self.closed) return;
    self.closed = true;
    const env = self.environment;
    const engine = try env.requireEngine();
    var s = LocalScope.init(engine);
    const ignored = try s.finish(self.closeBody(&s));
    engine.freeValue(ignored);
}
fn closeBody(self: *Scope, s: *LocalScope) !c.JSValue {
    const env = self.environment;
    // Stopping clears IDs and returns before frame restoration or idle reset.
    if (try self.stoppingCheck()) return c.pi_js_undefined();
    defer env.idle = true;
    var error_from_hook: ?anyerror = null;
    if (!self.failed and self.async_context.async_id != 0 and !self.flags.skip_async_hooks)
        env.emitAfter(self.async_context.async_id) catch |err| {
            s.boundary.escaping();
            error_from_hook = err;
        };
    if (self.pushed_ids) {
        _ = env.popAsyncContext(self.async_context.async_id) catch |err| failed_pop: {
            s.boundary.escaping();
            if (error_from_hook == null) error_from_hook = err;
            break :failed_pop false;
        };
        const displaced = try env.exchangeContextFrame(self.prior_frame);
        var old = displaced;
        s.boundary.release(&old);
    }
    if (error_from_hook) |err| return err;
    if (self.failed or env.callback_depth > 1 or self.flags.skip_task_queues or !env.canCallIntoJs())
        return c.pi_js_undefined();

INLINE static int uv__fd_hash_remove(int fd, struct uv__fd_info_s* info) {
  FIND_COMMON_VARIABLES

  uv_mutex_lock(&uv__fd_hash_mutex);

  FIND_IN_BUCKET_PTR();

  if (entry_ptr != NULL) {
    *info = entry_ptr->info;

    bucket_ptr->size -= 1;

    i = bucket_ptr->size % UV__FD_HASH_GROUP_SIZE;
    if (entry_ptr != &bucket_ptr->data->entries[i]) {
      *entry_ptr = bucket_ptr->data->entries[i];
    }

    if (bucket_ptr->size != 0 &&
        bucket_ptr->size % UV__FD_HASH_GROUP_SIZE == 0) {
      struct uv__fd_hash_entry_group_s* old_group_ptr = bucket_ptr->data;
      bucket_ptr->data = old_group_ptr->next;
      uv__free(old_group_ptr);
    }
  }

  uv_mutex_unlock(&uv__fd_hash_mutex);
  return entry_ptr != NULL;
}

int pi_uv_fs_close(PiUvFsRequest *request, int descriptor) {
    if (!pi_uv_fs_unsubmitted(request, PI_UV_FS_CLOSE)) return UV_EINVAL;
    request->descriptor = descriptor;
    PiUvCommand command = { .kind = PI_UV_CMD_FS_CLOSE, .fs_request = request };
    return pi_uv_fs_submit(request, &command, PI_UV_FS_CLOSE);
}
int pi_uv_fs_close_sync(PiUvService *service, struct uv_fs_s *request,
                        int descriptor) {
    assert(service != NULL && request != NULL);
    /* cb == NULL follows the actual synchronous libuv FS implementation.
     * No service command, queued completion, callback, or waiting count is
     * involved. The original caller traces and cleans its own stack request. */
    return uv_fs_close(&service->loop, request, descriptor, NULL);
